var n=`0450-skyr-cake`;var r=`world-0450`;var t=`IS`;var a=`northern-europe`;var s=8;var l=263;var g={en:`Skyr Cake`,ua:`Торт зі скіру`};var o={en:`A traditional dish from Iceland, centered on skyr, cream cheese, lemon juice, gelatin powder. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ісландія. Основні складники: скір, вершковий сир, лимонний сік, желатин у порошку. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Bloom the gelatin in a little cold water; dissolve gently, then whisk with skyr, cream cheese, sugar and lemon to make the filling.`,ua:`Замочіть желатин у невеликій кількості холодної води, обережно розчиніть і змішайте зі скіром, крем-сиром, цукром і лимоном для начинки.`,t:[`mixing`],m:7,i:[[`skyr`,500,`g`],[`cream-cheese`,230,`g`],[`white-granulated-sugar`,120,`g`],[`lemon-juice`,20,`ml`],[`gelatin-powder`,14,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:7,i:[[`graham-cracker-crumbs`,220,`g`],[`unsalted-butter`,90,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:6,i:[]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 240 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 240 хвилин.`,t:[`rapid-chilling`],m:240,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`blueberry`,180,`g`]]}];var h={slug:n,id:r,country:`IS`,region:a,servings:8,minutes:263,title:g,text:o,steps:d};export{t as country,h as default,r as id,l as minutes,a as region,s as servings,n as slug,d as steps,o as text,g as title};